/* Local-only persistence; no external database or synchronization endpoint. */
const localDbReady=new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(Error('IndexedDB unavailable'));return}const req=indexedDB.open('nunya-local',1);req.onupgradeneeded=()=>{const db=req.result;for(const name of ['snapshots','progress','notes','mastery','downloads','feedback'])if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
let localDbStatus='opening';
async function saveLocalDatabase(snapshot){try{const db=await localDbReady,id=snapshot.localProfileId||'default',updatedAt=new Date().toISOString();await new Promise((resolve,reject)=>{const tx=db.transaction(['snapshots','progress','notes','mastery','downloads','feedback'],'readwrite');tx.objectStore('snapshots').put({id,updatedAt,state:snapshot});tx.objectStore('progress').put({id,updatedAt,done:snapshot.done,resources:snapshot.resourceDone});tx.objectStore('notes').put({id,updatedAt,lessons:snapshot.notes,resources:snapshot.resourceNotes});tx.objectStore('mastery').put({id,updatedAt,values:snapshot.mastery,schedule:snapshot.reviewSchedule});tx.objectStore('downloads').put({id,updatedAt,courses:snapshot.downloads,resources:snapshot.resourceSaved});tx.objectStore('feedback').put({id,updatedAt,feedback:snapshot.feedback||[]});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});localDbStatus='ready'}catch{localDbStatus='fallback'}}
const persistLocalStorage=persist;
persist=function(){const ok=persistLocalStorage();saveLocalDatabase(JSON.parse(JSON.stringify(state)));return ok};
async function deleteProfileDatabase(id){try{const db=await localDbReady;await new Promise((resolve,reject)=>{const tx=db.transaction(['snapshots','progress','notes','mastery','downloads','feedback'],'readwrite');for(const name of tx.objectStoreNames)tx.objectStore(name).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch{}}
const removeLocalState=removeCurrentData;
removeCurrentData=async function(){await deleteProfileDatabase(state.localProfileId||'default');removeLocalState()};
saveLocalDatabase(JSON.parse(JSON.stringify(state)));
